import { buildReaderSchema, type VisibleVerse } from '../components/SEO/readerSchema';
import { bibleBookKeys } from '../data/bibleBookChapters';
import {
  BIBLE_EDITIONS,
  canonicalBook,
  editionChapterCount,
  getBibleEdition,
  isAvailableEdition,
} from '../data/bibleEditions';

export type StudyChapterRef = {
  edition: string;
  book: string;
  chapter: number;
};

const STUDY_CHAPTER = /^\/study\/([^/]+)\/([^/]+)\/(\d+)\/?$/;
const PRIVATE_HASH = /^#\/(login|profile|account|subscribe|payment-)/;

export function displayStudyBookName(book: string): string {
  const key = canonicalBook(book) || book;
  return key
    .replace(/^first/, '1 ')
    .replace(/^second/, '2 ')
    .replace(/^third/, '3 ')
    .replace(/([A-Z])/g, ' $1')
    .replace(/^./, (letter) => letter.toUpperCase())
    .replace(/\s+/g, ' ')
    .trim();
}

export function studyChapterPath(edition: string, book: string, chapter: number): string | null {
  const key = canonicalBook(book);
  if (!key || !isAvailableEdition(edition)) {
    return null;
  }
  if (!Number.isInteger(chapter) || chapter < 1 || chapter > editionChapterCount(key, edition)) {
    return null;
  }
  return `/study/${edition}/${key.toLowerCase()}/${chapter}/`;
}

export function parseStudyChapterPath(pathname: string): StudyChapterRef | null {
  const match = pathname.match(STUDY_CHAPTER);
  if (!match) {
    return null;
  }
  const edition = match[1];
  const book = canonicalBook(match[2]);
  const chapter = Number(match[3]);
  if (!book || !isAvailableEdition(edition)) {
    return null;
  }
  if (!Number.isInteger(chapter) || chapter < 1 || chapter > editionChapterCount(book, edition)) {
    return null;
  }
  return { edition, book, chapter };
}

export function shouldSyncStudyChapterUrl(pathname: string, hash = ''): boolean {
  return parseStudyChapterPath(pathname) !== null && !PRIVATE_HASH.test(hash);
}

export function listStudyChapterRefs(): StudyChapterRef[] {
  const refs: StudyChapterRef[] = [];
  for (const edition of BIBLE_EDITIONS) {
    for (const book of bibleBookKeys) {
      const last = editionChapterCount(book, edition.id);
      for (let chapter = 1; chapter <= last; chapter += 1) {
        refs.push({ edition: edition.id, book, chapter });
      }
    }
  }
  return refs;
}

/** Same passage in every enabled edition that actually has this chapter. */
export function studyChapterTranslationRefs(ref: StudyChapterRef): StudyChapterRef[] {
  const book = canonicalBook(ref.book);
  if (!book) {
    return [];
  }
  return BIBLE_EDITIONS.flatMap((edition) =>
    studyChapterPath(edition.id, book, ref.chapter)
      ? [{ edition: edition.id, book, chapter: ref.chapter }]
      : [],
  );
}

export function studyChapterAdjacentPaths(ref: StudyChapterRef): {
  previous: string | null;
  next: string | null;
} {
  return {
    previous: studyChapterPath(ref.edition, ref.book, ref.chapter - 1),
    next: studyChapterPath(ref.edition, ref.book, ref.chapter + 1),
  };
}

export function studyChapterTitle(ref: StudyChapterRef): string {
  const edition = getBibleEdition(ref.edition);
  return `${displayStudyBookName(ref.book)} ${ref.chapter} — ${edition.name} | Revelationary`;
}

export function studyChapterDescription(verses: readonly VisibleVerse[]): string {
  const text = verses
    .map((verse) => String(verse.text).trim())
    .filter(Boolean)
    .join(' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (!text) {
    return 'Read this Bible chapter for free on Revelationary.';
  }
  return text.length > 220 ? `${text.slice(0, 217).trimEnd()}...` : text;
}

export function studyChapterCanonical(ref: StudyChapterRef): string {
  const path = studyChapterPath(ref.edition, ref.book, ref.chapter);
  return `https://revelationary.online${path ?? '/study/'}`;
}

export function studyChapterSchema(ref: StudyChapterRef, verses: readonly VisibleVerse[]) {
  return buildReaderSchema({
    book: displayStudyBookName(ref.book),
    chapter: ref.chapter,
    translation: ref.edition,
    visibleVerses: [...verses],
    canonicalUrl: studyChapterCanonical(ref),
  });
}
